import XCTest
@testable import ClipbotCore

final class SecretFilterTests: XCTestCase {
    let filter = SecretFilter(ignoredBundleIDs: SecretFilter.defaultIgnoredBundleIDs)
    let text = ["public.utf8-plain-text"]

    func drops(_ f: SecretFilter, _ types: [String], _ app: String?) -> Bool {
        f.dropReason(types: types, sourceBundleIDs: Set([app].compactMap { $0 })) != nil
    }

    func testMarkerDropsRegardlessOfApp() {
        for marker in ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                       "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"] {
            XCTAssertTrue(drops(filter, text + [marker], "com.apple.TextEdit"), marker)
            XCTAssertTrue(drops(filter, [marker] + text, nil), marker)
        }
    }

    func testIgnoredAppDrops() {
        for app in ["com.1password.1password", "com.agilebits.onepassword7", "com.apple.Passwords", "com.apple.keychainaccess"] {
            XCTAssertTrue(drops(filter, text, app), app)
        }
        XCTAssertFalse(drops(filter, text, "com.apple.TextEdit"))
        XCTAssertFalse(drops(filter, text, nil))
    }

    func testCustomIgnoreListReplacesDefaults() {
        let custom = SecretFilter(ignoredBundleIDs: ["com.example.vault"])
        XCTAssertTrue(drops(custom, text, "com.example.vault"))
        // Marker types still win even with a custom list.
        XCTAssertTrue(drops(custom, ["org.nspasteboard.ConcealedType"], nil))
    }

    func testSecretPatterns() {
        let a40 = String(repeating: "aB3", count: 14)
        let secrets: [String] = [
            "sk-proj-" + a40,
            "sk-ant-api03-" + a40,
            "sk-" + a40,
            "ghp_" + String(a40.prefix(36)),
            "gho_" + String(a40.prefix(36)),
            "github_pat_" + a40 + "_" + String(a40.prefix(20)),
            "AKIAIOSFODNN7EXAMPLE",
            "ASIAIOSFODNN7EXAMPLE",
            "xoxb-1234-5678-abcdefghijkl",
            "sk_live_" + String(a40.prefix(24)),
            "rk_live_" + String(a40.prefix(24)),
            "-----BEGIN OPENSSH PRIVATE KEY-----\nabc\n-----END OPENSSH PRIVATE KEY-----",
            "here is my key:\n-----BEGIN RSA PRIVATE KEY-----\nMIIE\n-----END RSA PRIVATE KEY-----\n",
            "  \n ghp_" + String(a40.prefix(36)) + "\n",
            // Embedded in a line: .env files, shell exports, JSON, prose.
            "OPENAI_API_KEY=sk-proj-" + a40,
            "export AWS_ACCESS_KEY_ID=AKIAIOSFODNN7EXAMPLE",
            "{\"token\": \"ghp_" + String(a40.prefix(36)) + "\"}",
            "my key is sk-" + String(repeating: "a", count: 40) + " and more words",
            "-----BEGIN PGP PRIVATE KEY BLOCK-----\nabc\n-----END PGP PRIVATE KEY BLOCK-----",
        ]
        for s in secrets { XCTAssertTrue(SecretFilter.looksLikeSecret(s), s) }
    }

    func testNonSecretsKept() {
        let kept: [String] = [
            "sk-", "ask-me later", "Hello AKIA", "ghp_short", "AKIA",
            "I pushed it to github and opened a PR",
            "https://github.com/x", "-----BEGIN CERTIFICATE-----\nMIIB\n-----END CERTIFICATE-----",
            "Take the chance now to clean up any code that was rushed",
            "", "😀👍🏽",
        ]
        for s in kept { XCTAssertFalse(SecretFilter.looksLikeSecret(s), s) }
    }
}
